cd /work && python3 -c "
import pandas as pd,re
from collections import defaultdict
tr=pd.read_csv('b3_pvk_stack_train.csv')
def toks(s): return [t.strip() for t in re.split(r'\||;',str(s))]
for col in ['etl','htl']:
    d=defaultdict(list)
    for s,t in zip(tr[col],tr.target):
        for k in set(toks(s)): d[k].append(t)
    print('===',col)
    rows=[(k,len(v),sum(v)/len(v)) for k,v in d.items() if len(v)>=3]
    for k,n,m in sorted(rows,key=lambda x:-x[2]): print(f'{k:35s} {n:4d} {m:6.2f}')
"

